pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {demo} from "../src/demo.sol";

contract InvMutTest is Test {
    demo c;
    function setUp() public { c = new demo(); }

    function testFuzz_property(address from, bytes memory tosEncoded, uint256 v) public {
        address[] memory tos;
        if (tosEncoded.length == 0) {
            tos = new address[](1);
        } else {
            uint256 count = tosEncoded.length / 20;
            if (count == 0) {
                tos = new address[](1);
            } else {
                if (count > 20) count = 20;
                tos = new address[](count);
                for (uint i = 0; i < count; i++) {
                    uint256 start = i * 20;
                    bytes20 addrBytes;
                    assembly {
                        addrBytes := mload(add(add(tosEncoded, 0x20), start))
                    }
                    tos[i] = address(addrBytes);
                }
            }
        }

        Reverter r = new Reverter();

        if (tos.length == 0) {
            tos = new address[](1);
        }
        tos[0] = address(r);

        vm.assume(tos.length > 0);

        bool ok;
        try c.transfer(from, address(r), tos, v) {
            ok = true;
        } catch {
            ok = false;
        }

        assertTrue(!ok);
    }
}

contract Reverter {
    fallback() external payable {
        revert("revert");
    }
}
